import React, { useState, useEffect } from 'react';
import { INSTRUMENTS } from '../constants';
import { Instrument, AccountSettings } from '../types';
import { DollarSign, Percent, ArrowUpCircle, ArrowDownCircle, Crosshair, Lock, Target, Square, CheckSquare } from 'lucide-react';

interface CalculatorProps {
  settings: AccountSettings;
}

type CalcMode = 'FIXED_RISK' | 'FIXED_LOTS';

const Calculator: React.FC<CalculatorProps> = ({ settings }) => {
  // --- STATE ---
  const [instrument, setInstrument] = useState<Instrument>(INSTRUMENTS[0]);
  const [direction, setDirection] = useState<'BUY' | 'SELL'>('SELL');

  // Calculation Mode (Determines what changes when SL Distance changes)
  const [calcMode, setCalcMode] = useState<CalcMode>('FIXED_RISK');

  // Core Inputs
  const [balance, setBalance] = useState<number>(settings.balance);
  const [lotSize, setLotSize] = useState<number>(0);
  const [riskAmount, setRiskAmount] = useState<number>(0);
  const [riskPercent, setRiskPercent] = useState<number>(1); // Default 1%

  // Price Inputs
  const [entryPrice, setEntryPrice] = useState<number>(0);

  // Stop Loss
  const [slEnabled, setSlEnabled] = useState(true);
  const [slPrice, setSlPrice] = useState<number>(0);
  const [slDistance, setSlDistance] = useState<number>(0);

  // Take Profit
  const [tpEnabled, setTpEnabled] = useState(true);
  const [tpPrice, setTpPrice] = useState<number>(0);
  const [tpDistance, setTpDistance] = useState<number>(0);

  // Outputs
  const [rewardAmount, setRewardAmount] = useState<number>(0);
  const [rrRatio, setRrRatio] = useState<number>(0);

  // Helpers
  const isIndex = instrument.type === 'INDEX';
  const unitLabel = isIndex ? 'Pts' : 'Pips';
  const pricePrecision = instrument.pipSize === 0.01 || instrument.pipSize === 1 ? 2 : 5;

  // --- INITIALIZATION ---
  useEffect(() => {
    // Set default entry price if empty or switching types
    if (instrument.symbol === 'EURUSD') setEntryPrice(1.0850);
    else if (instrument.symbol === 'US30') setEntryPrice(34500);
    else if (instrument.symbol === 'NAS100') setEntryPrice(20500);
    else if (instrument.symbol === 'SPX500') setEntryPrice(5800);
    else if (instrument.symbol === 'XAUUSD') setEntryPrice(2025);
    else if (instrument.symbol === 'USDJPY') setEntryPrice(150.00);
    else if (instrument.symbol === 'EURJPY') setEntryPrice(163.50);
    else if (instrument.symbol === 'USDMXN') setEntryPrice(20.50);
    else setEntryPrice(0);

    // Set default SL distance
    const defaultSl = isIndex ? 50 : (instrument.symbol === 'USDMXN' ? 500 : 20);
    setSlDistance(defaultSl);

    // Trigger initial calc
    calculateFromRiskPercent(1, defaultSl, settings.balance);

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [instrument]);

  // --- RECALCULATION ON PRICE CHANGE ---
  useEffect(() => {
    if (entryPrice > 0 && slDistance > 0) {
        if (calcMode === 'FIXED_RISK') {
            calculateFromRiskAmount(riskAmount, slDistance, balance);
        } else {
            calculateFromLots(lotSize, slDistance, balance);
        }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [entryPrice]);


  // --- CALCULATION ENGINES ---

  const getValuePerUnit = () => {
    if (instrument.type === 'FOREX') {
       const rawPipValue = instrument.contractSize * instrument.pipSize;

       // 1. Quote Currency is USD
       if (instrument.symbol.endsWith('USD')) {
           return rawPipValue;
       }

       // 2. Contains JPY (USDJPY or EURJPY)
       if (instrument.symbol.includes('JPY')) {
           // For USDJPY, we use current price. For EURJPY, we approximate 
           // based on a standard USDJPY conversion (approx 150) if we don't have live feed.
           const conversion = instrument.symbol.startsWith('USD') ? entryPrice : 150;
           return conversion > 0 ? rawPipValue / conversion : 6.67;
       }

       // 3. Base Currency is USD (USDMXN, USDCAD)
       if (instrument.symbol.startsWith('USD')) {
           if (entryPrice > 0) return rawPipValue / entryPrice;
           if (instrument.symbol === 'USDMXN') return 0.5;
           return 10;
       }

       return 10; // Default for other crosses
    }

    if (instrument.symbol === 'XAUUSD') return 1;
    return instrument.contractSize; 
  };

  const calculateFromRiskPercent = (pct: number, dist: number, bal: number) => {
      const risk$ = bal * (pct / 100);
      setRiskPercent(pct);
      setRiskAmount(risk$);

      if (dist > 0) {
          const valPerUnit = getValuePerUnit();
          if (valPerUnit > 0) {
            const lots = risk$ / (dist * valPerUnit);
            setLotSize(Number(lots.toFixed(2)));
          }
      } else {
          setLotSize(0);
      }
  };

  const calculateFromRiskAmount = (amt: number, dist: number, bal: number) => {
      setRiskAmount(amt);
      setRiskPercent(Number(((amt / bal) * 100).toFixed(2)));

      if (dist > 0) {
          const valPerUnit = getValuePerUnit();
          if (valPerUnit > 0) {
            const lots = amt / (dist * valPerUnit);
            setLotSize(Number(lots.toFixed(2)));
          }
      }
  };

  const calculateFromLots = (lots: number, dist: number, bal: number) => {
      setLotSize(lots);
      if (dist > 0) {
          const valPerUnit = getValuePerUnit();
          const risk$ = lots * dist * valPerUnit;
          setRiskAmount(Number(risk$.toFixed(2)));
          setRiskPercent(Number(((risk$ / bal) * 100).toFixed(2)));
      }
  };

  const handleRiskPercentChange = (val: number) => {
      setCalcMode('FIXED_RISK');
      calculateFromRiskPercent(val, slDistance, balance);
  };

  const handleRiskAmountChange = (val: number) => {
      setCalcMode('FIXED_RISK');
      calculateFromRiskAmount(val, slDistance, balance);
  };

  const handleLotSizeChange = (val: number) => {
      setCalcMode('FIXED_LOTS');
      calculateFromLots(val, slDistance, balance);
  };

  const handleBalanceChange = (val: number) => {
      setBalance(val);
      calculateFromRiskPercent(riskPercent, slDistance, val);
  };

  const handleSlDistChange = (dist: number) => {
      setSlDistance(dist);
      if (entryPrice > 0) {
          const priceDist = dist * instrument.pipSize;
          const newPrice = direction === 'BUY' ? entryPrice - priceDist : entryPrice + priceDist;
          setSlPrice(Number(newPrice.toFixed(pricePrecision)));
      }
      if (calcMode === 'FIXED_RISK') {
          calculateFromRiskAmount(riskAmount, dist, balance);
      } else {
          calculateFromLots(lotSize, dist, balance);
      }
  };

  const handleSlPriceChange = (price: number) => {
      setSlPrice(price);
      if (entryPrice > 0) {
          const dist = Math.abs(entryPrice - price) / instrument.pipSize;
          const cleanDist = Number(dist.toFixed(1));
          setSlDistance(cleanDist);
          if (calcMode === 'FIXED_RISK') {
            calculateFromRiskAmount(riskAmount, cleanDist, balance);
          } else {
            calculateFromLots(lotSize, cleanDist, balance);
          }
      }
  };

  const handleEntryPriceChange = (price: number) => {
      setEntryPrice(price);
      if (price > 0 && slDistance > 0) {
          const slPriceDist = slDistance * instrument.pipSize;
          const newSlPrice = direction === 'BUY' ? price - slPriceDist : price + slPriceDist;
          setSlPrice(Number(newSlPrice.toFixed(pricePrecision)));
      }
      if (price > 0 && tpDistance > 0) {
          const tpPriceDist = tpDistance * instrument.pipSize;
          const newTpPrice = direction === 'BUY' ? price + tpPriceDist : price - tpPriceDist;
          setTpPrice(Number(newTpPrice.toFixed(pricePrecision)));
      }
  };

  const handleTpDistChange = (dist: number) => {
      setTpDistance(dist);
      if (entryPrice > 0) {
          const priceDist = dist * instrument.pipSize;
          const newPrice = direction === 'BUY' ? entryPrice + priceDist : entryPrice - priceDist;
          setTpPrice(Number(newPrice.toFixed(pricePrecision)));
      }
  };

  const handleTpPriceChange = (price: number) => {
      setTpPrice(price);
      if (entryPrice > 0) {
          const dist = Math.abs(entryPrice - price) / instrument.pipSize;
          setTpDistance(Number(dist.toFixed(1)));
      }
  };

  useEffect(() => {
    if (entryPrice > 0) {
        const slPriceDist = slDistance * instrument.pipSize;
        const tpPriceDist = tpDistance * instrument.pipSize;
        if (direction === 'BUY') {
            setSlPrice(Number((entryPrice - slPriceDist).toFixed(pricePrecision)));
            setTpPrice(Number((entryPrice + tpPriceDist).toFixed(pricePrecision)));
        } else {
            setSlPrice(Number((entryPrice + slPriceDist).toFixed(pricePrecision)));
            setTpPrice(Number((entryPrice - tpPriceDist).toFixed(pricePrecision)));
        }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [direction]);

  useEffect(() => {
      if (tpDistance > 0 && lotSize > 0) {
          const valPerUnit = getValuePerUnit();
          const reward = lotSize * tpDistance * valPerUnit;
          setRewardAmount(Number(reward.toFixed(2)));
          if (riskAmount > 0) {
            setRrRatio(Number((reward / riskAmount).toFixed(2)));
          }
      } else {
          setRewardAmount(0);
          setRrRatio(0);
      }
  }, [tpDistance, lotSize, riskAmount, instrument, entryPrice]);


  return (
    <div className="w-full max-w-5xl mx-auto p-4 md:p-6 animate-fade-in">

        {/* Header */}
        <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
            <div>
                 <h2 className="text-3xl font-serif text-white mb-1">Risk Calculator</h2>
                 <p className="text-slate-500 text-sm">Bi-directional position sizing.</p>
            </div>
             <div className="relative z-20">
                 <select 
                    value={instrument.symbol}
                    onChange={(e) => setInstrument(INSTRUMENTS.find(i => i.symbol === e.target.value) || INSTRUMENTS[0])}
                    className="appearance-none bg-slate-900 border border-slate-700 text-gold-400 font-bold py-2 px-6 pr-10 rounded-full text-sm outline-none focus:border-gold-500 transition-all cursor-pointer shadow-lg"
                 >
                    {INSTRUMENTS.map(i => <option key={i.symbol} value={i.symbol}>{i.symbol}</option>)}
                 </select>
             </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

            {/* --- LEFT COLUMN: CONTROLS (Cols 1-7) --- */}
            <div className="lg:col-span-7 space-y-6">

                {/* --- 2x2 CONTROL GRID --- */}
                <div className="bg-slate-900 rounded-2xl p-5 border border-slate-800 shadow-xl space-y-5">

                    {/* Row 1: Balance & Lots */}
                    <div className="grid grid-cols-2 gap-5">
                        {/* Balance */}
                        <div>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-wider mb-2 block">Balance</label>
                            <div className="relative group">
                                <DollarSign size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-600 group-focus-within:text-gold-500 transition-colors" />
                                <input 
                                    type="number" 
                                    value={balance}
                                    onChange={(e) => handleBalanceChange(Number(e.target.value))}
                                    className="w-full bg-slate-950 border border-slate-700 text-white pl-9 pr-3 py-3 rounded-xl font-bold outline-none focus:border-gold-500 transition-all shadow-inner"
                                />
                            </div>
                        </div>

                        {/* Lot Size (Input) */}
                        <div>
                            <div className="flex justify-between items-center mb-2">
                                <label className="text-[10px] uppercase text-gold-500 font-bold tracking-wider block">Lot Size</label>
                                {calcMode === 'FIXED_LOTS' && <Lock size={12} className="text-gold-500" />}
                            </div>
                            <div className="relative group">
                                <input 
                                    type="number" 
                                    value={lotSize}
                                    onChange={(e) => handleLotSizeChange(Number(e.target.value))}
                                    className={`w-full bg-slate-950 border text-white px-4 py-3 rounded-xl font-mono text-lg font-bold outline-none transition-all shadow-inner ${calcMode === 'FIXED_LOTS' ? 'border-gold-500/50 shadow-[0_0_10px_rgba(212,175,55,0.05)]' : 'border-slate-700 focus:border-gold-500'}`}
                                />
                                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-slate-600 font-bold">LOTS</span>
                            </div>
                        </div>
                    </div>

                    <div className="h-px bg-slate-800 w-full" />

                    {/* Row 2: Risk $ & Risk % */}
                    <div className="grid grid-cols-2 gap-5">
                        {/* Risk $ */}
                        <div>
                            <div className="flex justify-between items-center mb-2">
                                <label className="text-[10px] uppercase text-rose-400 font-bold tracking-wider block">Risk ($)</label>
                                {calcMode === 'FIXED_RISK' && <Lock size={12} className="text-rose-500" />}
                            </div>
                            <div className="relative group">
                                <DollarSign size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-600" />
                                <input 
                                    type="number" 
                                    value={riskAmount}
                                    onChange={(e) => handleRiskAmountChange(Number(e.target.value))}
                                    className={`w-full bg-slate-950 border text-rose-400 pl-9 pr-3 py-3 rounded-xl font-bold outline-none transition-all ${calcMode === 'FIXED_RISK' ? 'border-rose-500/40' : 'border-slate-700 focus:border-rose-500'}`}
                                />
                            </div>
                        </div>

                        {/* Risk % */}
                        <div>
                            <div className="flex justify-between items-center mb-2">
                                <label className="text-[10px] uppercase text-slate-500 font-bold tracking-wider block">Risk (%)</label>
                            </div>
                            <div className="relative group">
                                <Percent size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-600" />
                                <input 
                                    type="number" 
                                    value={riskPercent}
                                    step="0.1"
                                    onChange={(e) => handleRiskPercentChange(Number(e.target.value))}
                                    className={`w-full bg-slate-950 border text-white pl-9 pr-3 py-3 rounded-xl font-bold outline-none transition-all ${calcMode === 'FIXED_RISK' ? 'border-rose-500/40' : 'border-slate-700 focus:border-rose-500'}`}
                                />
                            </div>
                        </div>
                    </div>
                </div>

                {/* --- ENTRY & DIRECTION --- */}
                <div className="bg-slate-900 rounded-2xl p-5 border border-slate-800 shadow-xl space-y-4">
                    <div className="flex items-end justify-between px-1">
                        <label className="text-[10px] uppercase text-slate-500 font-bold tracking-wider">Entry Price</label>
                        <span className="text-[10px] text-gold-500 bg-gold-500/10 px-2 py-0.5 rounded">Current Market</span>
                    </div>

                    <div className="relative group">
                        <Crosshair className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" size={18} />
                        <input 
                            type="number" 
                            value={entryPrice || ''} 
                            onChange={(e) => handleEntryPriceChange(Number(e.target.value))}
                            className="w-full bg-slate-950 border border-slate-700 text-center text-2xl font-medium text-white py-4 rounded-xl focus:ring-1 focus:ring-gold-500 focus:border-gold-500 outline-none transition-all placeholder-slate-700"
                            placeholder="0.0000"
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <button
                            onClick={() => setDirection('SELL')}
                            className={`py-3 rounded-xl border transition-all duration-200 flex items-center justify-center gap-2 ${
                                direction === 'SELL' 
                                ? 'bg-rose-500/10 border-rose-500 text-rose-500 shadow-[0_0_15px_rgba(244,63,94,0.15)]' 
